@Polynomial.splits_iff_exists_multiset : ∀ {R : Type u_1} [inst : CommRing R] {f : Polynomial R},
  f.Splits ↔ ∃ m, f = Polynomial.C f.leadingCoeff * (Multiset.map (fun x => Polynomial.X - Polynomial.C x) m).prod
@Polynomial.Splits : {R : Type u_1} → [inst : Semiring R] → Polynomial R → Prop
def Polynomial.Splits.{u_1} : {R : Type u_1} → [inst : Semiring R] → Polynomial R → Prop :=
fun {R} [Semiring R] f =>
  f ∈ Submonoid.closure ({x | ∃ a, Polynomial.C a = x} ∪ {x | ∃ a, Polynomial.X + Polynomial.C a = x})

